input.command:
python3 -c "
import json
with open('/root/DATA/products/CoachForce.json') as f:
    data = json.load(f)
if isinstance(data, list):
    print('Type: list, Length:', len(data))
    print('First item keys:', list(data[0].keys()) if data else 'empty')
    print('First item:', json.dumps(data[0], indent=2)[:2000])
elif isinstance(data, dict):
    print('Type: dict, Keys:', list(data.keys()))
    for k in list(data.keys())[:5]:
        v = data[k]
        print(f'  {k}: type={type(v).__name__}')
        if isinstance(v, str):
            print(f'    value: {v[:200]}')
        elif isinstance(v, list):
            print(f'    len={len(v)}')
            if v:
                print(f'    first item: {json.dumps(v[0], indent=2)[:500]}')
"

